import os

def load():
    cfg = {}
    # CACHE_DIR is deliberately ignored unless ENABLE_CACHE=1 is ALSO set —
    # a half-configured cache dir caused silent disk fills in production, so
    # both must be present or caching stays off entirely.
    if os.environ.get('ENABLE_CACHE') == '1':
        cfg['cache_dir'] = os.environ.get('CACHE_DIR', '/tmp/cache')
    return cfg

